def is_leap_year(year):
    """Check if a given year is a leap year."""

    # A year is a leap year if it is evenly divisible by 4,
    # except for years that are evenly divisible by 100.
    # Those centurial years (years ending in '00') need to 
    # also be divisible by 400 to be a leap year.

    if year % 4 != 0:
        return False
    elif year % 100 != 0:
        return True
    elif year % 400 != 0:
        return False
    else:
        return True

