from backend.services.phones.data.schemas import BasePhone


class PhonesRepo:

    def __init__(self, table):  # type: ignore
        self.table = table

    def get_all(self) -> List[BasePhone]:
        phones = self.table.scan()
        return [BasePhone(**phone) for phone in phones]

    def create(self, phone: BasePhone) -> BasePhone:
        self.table.put_item(Item=phone.dict())
        return phone

    def update(self, phone: BasePhone) -> Optional[BasePhone]:
        self.table.update_item(
            Key={"id": phone.id},
            UpdateExpression="set #nm = :n, #ph = :p",
            ExpressionAttributeNames={
                "#nm": "name",
                "#ph": "phone",
            },
            ExpressionAttributeValues={
                ":n": phone.name,
                ":p": phone.phone,
            },
            ReturnValues="UPDATED_NEW"
        )
        return phone

    def delete(self, id_: int) -> Optional[BasePhone]:
        phone = self.get_by_id(id_)
        if phone:
            self.table.delete_item(Key={"id": id_, })
        return phone

    def get_by_id(self, id_: int) -> Optional[BasePhone]:
        response = self.table.get_item(
            Key={"id": id_}
        )
        if "Item" in response:
            return BasePhone(**response["Item"])
        return None
